   121	/**
   122	 * A task needs two things to be created - a title and a parent report
   123	 * When you create a task report, there are a few things that happen:
   124	 * A task report is created, along with a CreatedReportAction for that new task report
   125	 * A reportAction indicating that a task was created is added to the parent report (share destination)
   126	 * If you assign the task to someone, a reportAction is created in the chat between you and the assignee to inform them of the task
   127	 *
   128	 * So you have the following optimistic items potentially being created:
   129	 * 1. The task report
   130	 * 1a. The CreatedReportAction for the task report
   131	 * 2. The TaskReportAction on the parent report
   132	 * 3. The chat report between you and the assignee
   133	 * 3a. The CreatedReportAction for the assignee chat report
   134	 * 3b. The TaskReportAction on the assignee chat report
   135	 */
   136	function createTaskAndNavigate(
   137	    parentReportID: string | undefined,
   138	    title: string,
   139	    description: string,
   140	    assigneeEmail: string,
   141	    assigneeAccountID = 0,
   142	    assigneeChatReport?: OnyxEntry<OnyxTypes.Report>,
   143	    policyID: string = CONST.POLICY.OWNER_EMAIL_FAKE,
   144	    isCreatedUsingMarkdown = false,
   145	) {
   146	    if (!parentReportID) {
   147	        return;
   148	    }
   149	
   150	    const optimisticTaskReport = ReportUtils.buildOptimisticTaskReport(currentUserAccountID, parentReportID, assigneeAccountID, title, description, policyID);
   151	
   152	    const assigneeChatReportID = assigneeChatReport?.reportID;
   153	    const taskReportID = optimisticTaskReport.reportID;
   154	    let assigneeChatReportOnyxData;
   155	
   156	    // Parent ReportAction indicating that a task has been created
   157	    const optimisticTaskCreatedAction = ReportUtils.buildOptimisticCreatedReportAction(currentUserEmail);
   158	    const optimisticAddCommentReport = ReportUtils.buildOptimisticTaskCommentReportAction(taskReportID, title, assigneeAccountID, `task for ${title}`, parentReportID);
   159	    optimisticTaskReport.parentReportActionID = optimisticAddCommentReport.reportAction.reportActionID;
   160	
   161	    const currentTime = DateUtils.getDBTimeWithSkew();
   162	    const lastCommentText = ReportUtils.formatReportLastMessageText(ReportActionsUtils.getReportActionText(optimisticAddCommentReport.reportAction));
   163	    const parentReport = allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`];
   164	    const optimisticParentReport = {
   165	        lastVisibleActionCreated: optimisticAddCommentReport.reportAction.created,
   166	        lastMessageText: lastCommentText,
   167	        lastActorAccountID: currentUserAccountID,
   168	        lastReadTime: currentTime,
   169	        hasOutstandingChildTask: assigneeAccountID === currentUserAccountID ? true : parentReport?.hasOutstandingChildTask,
   170	    };
   171	
   172	    // We're only setting onyx data for the task report here because it's possible for the parent report to not exist yet (if you're assigning a task to someone you haven't chatted with before)
   173	    // So we don't want to set the parent report data until we've successfully created that chat report
   174	    // FOR TASK REPORT
