   371	function getOutstandingChildTask(taskReport: OnyxEntry<OnyxTypes.Report>) {
   372	    const parentReportActions = allReportActions?.[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${taskReport?.parentReportID}`] ?? {};
   373	    return Object.values(parentReportActions).some((reportAction) => {
   374	        if (String(reportAction.childReportID) === String(taskReport?.reportID)) {
   375	            return false;
   376	        }
   377	
   378	        if (
   379	            reportAction.childType === CONST.REPORT.TYPE.TASK &&
   380	            reportAction?.childStateNum === CONST.REPORT.STATE_NUM.OPEN &&
   381	            reportAction?.childStatusNum === CONST.REPORT.STATUS_NUM.OPEN &&
   382	            !ReportActionsUtils.getReportActionMessage(reportAction)?.isDeletedParentAction
   383	        ) {
   384	            return true;
   385	        }
   386	
   387	        return false;
   388	    });
   389	}
